SELECT * FROM TBL_SETTLEMENT_EXCEPTION

    DELETE_FLAG = 0

        AND EXCEPTION_NO LIKE CONCAT('%', #{exceptionNo}, '%')


        AND EXCEPTION_LEVEL = #{exceptionLevel}


        AND EXCEPTION_STATUS = #{exceptionStatus}


        AND ASSIGNEE = #{assignee}


        AND ORG_ID = #{orgId}


        AND CREATE_TIME >= #{beginTime}


        AND CREATE_TIME <= #{endTime}


ORDER BY CREATE_TIME DESC

    LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM TBL_SETTLEMENT_EXCEPTION

    DELETE_FLAG = 0

        AND EXCEPTION_NO LIKE CONCAT('%', #{exceptionNo}, '%')


        AND EXCEPTION_LEVEL = #{exceptionLevel}


        AND EXCEPTION_STATUS = #{exceptionStatus}


        AND ASSIGNEE = #{assignee}


        AND ORG_ID = #{orgId}


        AND CREATE_TIME >= #{beginTime}


        AND CREATE_TIME <= #{endTime}

SELECT COUNT(CASE WHEN EXCEPTION_LEVEL = 'CRITICAL' THEN 1 END) AS criticalCount, COUNT(CASE WHEN EXCEPTION_LEVEL = 'HIGH' THEN 1 END) AS highCount, COUNT(CASE WHEN EXCEPTION_LEVEL = 'MEDIUM' THEN 1 END) AS mediumCount, COUNT(CASE WHEN EXCEPTION_LEVEL = 'LOW' THEN 1 END) AS lowCount, COUNT(CASE WHEN EXCEPTION_STATUS = 'OPEN' THEN 1 END) AS openCount, COUNT(CASE WHEN EXCEPTION_STATUS = 'ASSIGNED' THEN 1 END) AS assignedCount, COUNT(CASE WHEN EXCEPTION_STATUS = 'RESOLVED' THEN 1 END) AS resolvedCount, COUNT(*) AS totalCount, COALESCE(SUM(CASE WHEN EXCEPTION_STATUS = 'RESOLVED' THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 0) AS resolutionRate FROM TBL_SETTLEMENT_EXCEPTION WHERE DELETE_FLAG = 0
AND ORG_ID = #{orgId}
AND CREATE_TIME >= #{beginTime}
AND CREATE_TIME <= #{endTime}

SELECT DATE_FORMAT(CREATE_TIME, '%Y-%m-%d') AS datePoint, COUNT(CASE WHEN EXCEPTION_LEVEL = 'CRITICAL' THEN 1 END) AS criticalCount, COUNT(CASE WHEN EXCEPTION_LEVEL = 'HIGH' THEN 1 END) AS highCount, COUNT(CASE WHEN EXCEPTION_LEVEL = 'MEDIUM' THEN 1 END) AS mediumCount, COUNT(CASE WHEN EXCEPTION_LEVEL = 'LOW' THEN 1 END) AS lowCount, COUNT(*) AS totalCount, COUNT(CASE WHEN EXCEPTION_STATUS = 'RESOLVED' THEN 1 END) AS resolvedCount FROM TBL_SETTLEMENT_EXCEPTION WHERE DELETE_FLAG = 0
AND ORG_ID = #{orgId}
AND CREATE_TIME >= #{beginTime}
AND CREATE_TIME <= #{endTime}
GROUP BY DATE_FORMAT(CREATE_TIME, '%Y-%m-%d') ORDER BY datePoint ASC
